import{_ as h,o as i,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"&quot;Điểm cao ≠ hiểu sâu&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/diem-cao.md","filePath":"mental-models/diem-cao.md"}'),c={name:"mental-models/diem-cao.md"};function o(g,n,u,e,m,r){return i(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="quot-điem-cao-hieu-sau-quot" tabindex="-1">&quot;Điểm cao ≠ hiểu sâu&quot; <a class="header-anchor" href="#quot-điem-cao-hieu-sau-quot" aria-label="Permalink to &quot;&amp;quot;Điểm cao ≠ hiểu sâu&amp;quot;&quot;">​</a></h1><p>Trên trang này# &quot;Điểm cao ≠ hiểu sâu&quot; <a href="#điem-cao-hieu-sau">​</a> Điểm số đo được nhiều thứ cùng lúc: hiểu bài, thuộc dạng, cẩn thận, tốc độ, may mắn, mức quen với cách ra đề của thầy cô. &quot;Hiểu sâu&quot; chỉ là một trong số đó — và thường không phải phần lớn nhất.</p><h2 id="bon-cach-đat-điem-cao-ma-khong-hieu-​" tabindex="-1">Bốn cách đạt điểm cao mà không hiểu <a href="#bon-cach-đat-điem-cao-ma-khong-hieu">​</a> <a class="header-anchor" href="#bon-cach-đat-điem-cao-ma-khong-hieu-​" aria-label="Permalink to &quot;Bốn cách đạt điểm cao mà không hiểu [​](#bon-cach-đat-điem-cao-ma-khong-hieu)&quot;">​</a></h2><p><strong>Thuộc dạng.</strong> Làm 200 bài cùng kiểu thì nhận ra khuôn mẫu và áp dụng đúng quy trình — mà không hiểu vì sao quy trình đó đúng. Đổi cách hỏi một chút là hỏng. <strong>Trúng tủ.</strong> Đề rơi vào đúng phần đã ôn kỹ. Điểm 9 nói về sự trùng khớp giữa đề và phần đã ôn, không nói về toàn bộ môn học. <strong>Loại trừ.</strong> Với trắc nghiệm, kỹ năng loại phương án cho điểm khá cao mà không cần biết đáp án đúng vì sao đúng. <strong>Cẩn thận.</strong> Hai học sinh hiểu như nhau, một em cẩn thận hơn được cao hơn một điểm. Điểm chênh đó nói về sự tỉ mỉ, không nói về hiểu biết. Không cách nào trong bốn cách này là gian lận. Chúng là những kỹ năng thật và có ích. Chỉ là chúng không phải thứ bạn tưởng mình đang đo.</p><h2 id="chieu-nguoc-lai-cung-đung-​" tabindex="-1">Chiều ngược lại cũng đúng <a href="#chieu-nguoc-lai-cung-đung">​</a> <a class="header-anchor" href="#chieu-nguoc-lai-cung-đung-​" aria-label="Permalink to &quot;Chiều ngược lại cũng đúng [​](#chieu-nguoc-lai-cung-đung)&quot;">​</a></h2><p>Điểm thấp không tự động nghĩa là không hiểu:</p><ul><li>Hiểu bài nhưng đọc sót một chữ trong đề.</li><li>Hiểu bài nhưng làm chậm, không kịp giờ.</li><li>Hiểu bài nhưng đêm qua ngủ 4 tiếng.</li><li>Hiểu bài nhưng bị đề hỏi theo cách chưa từng gặp — và đây thực ra là dấu hiệu tốt về đề, không phải dấu hiệu xấu về học sinh.</li></ul><h2 id="dau-hieu-phan-biet-​" tabindex="-1">Dấu hiệu phân biệt <a href="#dau-hieu-phan-biet">​</a> <a class="header-anchor" href="#dau-hieu-phan-biet-​" aria-label="Permalink to &quot;Dấu hiệu phân biệt [​](#dau-hieu-phan-biet)&quot;">​</a></h2><p>Điểm cao, hiểu nôngLàm được bài quen, hỏng khi đổi cách hỏi · Không giải thích được vì sao làm bước đó · Không biết khi nào cách này không dùng được · Ba tháng sau quên sạch · Không nhận ra kiến thức này liên quan gì tới phần khác Hiểu sâu thậtLàm được bài lạ cùng nguyên tắc · Giải thích được cho người khác · Biết giới hạn áp dụng · Ước lượng được đáp án có hợp lý không trước khi tính · Nối được sang các mảng khác · Sáu tháng sau nhắc là nhớ lại nhanh Cách thử nhanh nhất, làm được ngay tối nay: <strong>bảo con giải thích cho bạn nghe, không mở vở.</strong> Chỗ nào con ấp úng là chỗ đang mỏng — kể cả khi bài kiểm tra chỗ đó được 9 điểm.</p><h2 id="vi-sao-hieu-lam-nay-dai-dang-​" tabindex="-1">Vì sao hiểu lầm này dai dẳng <a href="#vi-sao-hieu-lam-nay-dai-dang">​</a> <a class="header-anchor" href="#vi-sao-hieu-lam-nay-dai-dang-​" aria-label="Permalink to &quot;Vì sao hiểu lầm này dai dẳng [​](#vi-sao-hieu-lam-nay-dai-dang)&quot;">​</a></h2><p>Vì điểm số là thứ <strong>duy nhất</strong> được đo và báo về đều đặn. Nhà trường đo, gia đình nhận, và không có con số nào khác để đặt cạnh. Khi chỉ có một thước đo, nó tự động trở thành mục tiêu — dù không ai chủ ý quyết định như vậy. Và khi nó trở thành mục tiêu, bốn con đường tắt ở trên trở nên hấp dẫn một cách hoàn toàn hợp lý với một đứa trẻ.</p><h2 id="nemo12-lam-gi-khac-​" tabindex="-1">Nemo12 làm gì khác <a href="#nemo12-lam-gi-khac">​</a> <a class="header-anchor" href="#nemo12-lam-gi-khac-​" aria-label="Permalink to &quot;Nemo12 làm gì khác [​](#nemo12-lam-gi-khac)&quot;">​</a></h2><p><strong>Đo mức sâu, không chỉ đúng-sai.</strong> Sáu bậc từ nhận ra tới dùng được trong tình huống lạ. Điểm cao ở bậc thấp không được ghi nhận là đã vững. <a href="/learning/hoc-ky">Xem sáu bậc →</a><strong>Đòi bằng chứng đa dạng.</strong> Mười câu đúng cùng một dạng cho độ chắc chắn thấp hơn hẳn mười câu đúng ở năm dạng khác nhau — chính vì &quot;thuộc dạng&quot; là chuyện có thật. <strong>Hỏi cách nghĩ, không chỉ đáp án.</strong> Sau khi chọn, learner nói mình đã làm thế nào: suy ra, nhớ lại, loại trừ, hay đoán. Đúng bằng cách loại trừ được ghi nhận khác với đúng bằng cách suy luận. <strong>Trộn dạng bài.</strong> Kiểm tra ở ngữ cảnh lạ là cách duy nhất phân biệt hiểu và thuộc.</p><h2 id="đieu-nay-co-nghia-la-bo-qua-điem-so-khong-​" tabindex="-1">Điều này có nghĩa là bỏ qua điểm số không? <a href="#đieu-nay-co-nghia-la-bo-qua-điem-so-khong">​</a> <a class="header-anchor" href="#đieu-nay-co-nghia-la-bo-qua-điem-so-khong-​" aria-label="Permalink to &quot;Điều này có nghĩa là bỏ qua điểm số không? [​](#đieu-nay-co-nghia-la-bo-qua-điem-so-khong)&quot;">​</a></h2><p>Không. Điểm số vẫn quan trọng thật — nó là cánh cửa vào trường tốt, và đó không phải chuyện tưởng tượng. Đề nghị ở đây khiêm tốn hơn nhiều: <strong>đừng dùng điểm số làm bằng chứng về việc hiểu</strong>. Dùng nó cho đúng việc nó làm được — đo kết quả trong một kỳ thi cụ thể — và dùng cách khác để biết con có hiểu hay không. Đổi một câu hỏi Thay vì <em>&quot;Con được mấy điểm?&quot;</em> — thử: <strong>&quot;Bài nào khó nhất? Con làm thế nào?&quot;</strong> Câu thứ hai cho bạn nhiều thông tin hơn hẳn, và nó cũng không biến bữa cơm thành buổi báo cáo kết quả. Điểm số là một phép đo có nhiễu về một phần của việc hiểu. Rất hữu ích — chỉ là đừng nhầm nó với chính việc hiểu. <a href="/mental-models/lam-nhieu-bai">Làm nhiều bài ≠ học tốt →</a></p>',15)])])}const k=h(c,[["render",o]]);export{s as __pageData,k as default};
